import React from 'react';

const Header = () => {
  const containerStyle = {
    position: 'sticky',
    top: 0,
    zIndex: 1000,
    background: 'linear-gradient(90deg, var(--primary-maroon-dark) 0%, rgba(54,69,79,0.6) 60%)',
    backdropFilter: 'blur(12px)',
    WebkitBackdropFilter: 'blur(12px)',
    borderBottom: '1px solid rgba(212,175,55,0.06)',
  };

  const innerStyle = {
    maxWidth: '1400px',
    margin: '0 auto',
    padding: '12px 40px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  };

  const logoStyle = {
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
    cursor: 'pointer',
  };

  const logoTextStyle = {
    color: 'var(--accent-gold)',
    fontSize: '20px',
    fontWeight: 800,
    margin: 0,
    letterSpacing: '-0.4px',
  };

  const navStyle = {
    display: 'flex',
    gap: '28px',
    alignItems: 'center',
  };

  const linkStyle = {
    color: 'rgba(255,255,255,0.85)',
    textDecoration: 'none',
    fontWeight: 500,
    fontSize: '15px',
    letterSpacing: '0.3px',
    paddingBottom: '4px',
    borderBottom: '2px solid transparent',
    transition: 'color 0.28s ease, border-bottom-color 0.28s ease',
  };

  return (
    <header style={containerStyle}>
      <div style={innerStyle}>
        <div style={logoStyle}>

          <h1 style={logoTextStyle}>Artemis</h1>
        </div>

        <nav style={navStyle}>
          <a
            href="/"
            style={linkStyle}
            onMouseEnter={(e) => {
              e.currentTarget.style.color = 'var(--accent-gold)';
              e.currentTarget.style.borderBottomColor = 'var(--accent-gold)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.color = 'rgba(255,255,255,0.85)';
              e.currentTarget.style.borderBottomColor = 'transparent';
            }}
          >
            Home
          </a>
        </nav>
      </div>
    </header>
  );
};

export default Header;
